// Generated by scaffold-migration-prod — TypeORM migration sort-order safety net.
//
// TypeORM sorts migrations by the LAST 13 characters of the class name
// (MigrationExecutor.getMigrations: parseInt(className.substr(-13))). A class
// named with a 14-digit YYYYMMDDHHMMSS timestamp (e.g. ...20260507000000) loses
// its leading digit -> a smaller key -> it sorts BEFORE the 13-digit epoch base
// migrations, so `migration:run` on a fresh DB can run an ALTER before its CREATE.
// Prefer 13-digit epoch timestamps (use `migration:generate`); this re-sorts
// getMigrations() by the FULL trailing number as a safety net. No-op for correct
// 13-digit names, and can't affect an already-migrated DB (matching is by name).
import { MigrationExecutor } from 'typeorm';

const proto = MigrationExecutor.prototype as unknown as {
    getMigrations?: () => Array<{ name?: string }>;
    __migrationOrderPatched?: boolean;
};

// Normalise to a real chronological key (epoch ms) so 13-digit epoch names AND
// 14-digit YYYYMMDDHHMMSS names sort correctly TOGETHER — even a future 13-digit
// epoch still sorts after a 14-digit date, which a plain full-number sort misses.
function chronoKey(name: string | undefined): number {
    const match = /(\d+)$/.exec(String(name ?? ''));
    if (!match) return 0;
    const d = match[1];
    if (d.length === 14) {
        const y = +d.slice(0, 4);
        const mo = +d.slice(4, 6);
        const day = +d.slice(6, 8);
        const h = +d.slice(8, 10);
        const mi = +d.slice(10, 12);
        const s = +d.slice(12, 14);
        if (y >= 2000 && y <= 2999 && mo >= 1 && mo <= 12 && day >= 1 && day <= 31) {
            const t = Date.UTC(y, mo - 1, day, h, mi, s);
            if (!Number.isNaN(t)) return t;
        }
    }
    return Number(d);
}

if (
    proto &&
    typeof proto.getMigrations === 'function' &&
    !proto.__migrationOrderPatched
) {
    const original = proto.getMigrations;
    proto.getMigrations = function patchedGetMigrations() {
        return original
            .call(this)
            .slice()
            .sort((a, b) => chronoKey(a.name) - chronoKey(b.name));
    };
    proto.__migrationOrderPatched = true;
}
